 function t(value){
  const key=typeof value==='number'?payload.keys[value]:value;
  if(language==='pl'||typeof key!=='string')return key;
  const exact=table[key];
  if(exact)return exact[localeIndex()]??key;
  for(const [re,ru,en,uk] of patterns){const m=key.match(re);if(m)return interpolate(language==='ru'?ru:language==='en'?en:uk,m.slice(1).map(x=>table[x]?.[localeIndex()]??x));}
  // Controlled status strings only; report cells are never passed through here.
  if(key.includes(' · '))return key.split(' · ').map(t).join(' · ');
  if(key.startsWith('Błąd: '))return (language==='ru'?'Ошибка: ':language==='uk'?'Помилка: ':'Error: ')+t(key.slice(6));
  if(key.startsWith('Błąd analizy: '))return (language==='ru'?'Ошибка анализа: ':language==='uk'?'Помилка аналізу: ':'Analysis error: ')+t(key.slice('Błąd analizy: '.length));
  return key;
 }
